INSERT INTO public.hospitals (id, name, name_ta, tagline, tagline_ta, is_sample_data, sample_disclaimer, sample_disclaimer_ta, address, address_ta, city, phone, emergency_phone, email, latitude, longitude, visiting_hours, visiting_hours_ta) VALUES ('11111111-1111-4111-8111-111111111101', 'Aurelia Pavilion Medical Center', 'ஆரேலியா பெவிலியன் மருத்துவ மையம்', 'Find Your Way. Access Care. Save Time.', 'உங்கள் வழியைக் கண்டறியுங்கள். மருத்துவ சேவையைப் பெறுங்கள். நேரத்தைச் சேமியுங்கள்.', true, 'Fictional sample hospital layout and clinical dataset created strictly for MEDIPATH navigation and platform demonstration.', 'MEDIPATH வழிகாட்டுதல் மற்றும் செயல்விளக்கத்திற்காக உருவாக்கப்பட்ட மாதிரி மருத்துவமனை அமைப்பு.', '42 Cathedral Promenade, Civic Medical District, Chennai 600006', '42 கதீட்ரல் பிராமனேட், சிவில் மருத்துவ மண்டலம், சென்னை 600006', 'Chennai', '+91 44 4019 2200', '+91 44 4019 2911', 'concierge@aurelia-sample.medipath.org', 13.0604, 80.2496, 'Outpatient 07:00 – 21:00 · Emergency & Trauma 24/7', 'புறநோயாளர் 07:00 – 21:00 · அவசர சிகிச்சை 24/7') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.buildings (id, hospital_id, name, name_ta, code, description, description_ta, total_floors, width_meters, depth_meters) VALUES ('22222222-2222-4222-8222-222222222201', '11111111-1111-4111-8111-111111111101', 'Main Architectural Pavilion', 'முதன்மை மருத்துவக் கட்டிடம்', 'PAV-A', 'Four-level limestone and glass pavilion unified around a central daylight atrium, dual elevator cores, and step-free clinical wings.', 'நான்கு தளங்களைக் கொண்ட சுண்ணாம்பு மற்றும் கண்ணாடி முகப்பு மருத்துவக் கட்டிடம்; மைய மின்தூக்கிகள் மற்றும் சக்கர நாற்காலி அணுகல் பாதைகளுடன்.', 4, 48, 30) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.map_versions (id, hospital_id, version_number, label, status, published_by, published_at, notes) VALUES ('33333333-3333-4333-8333-333333333301', '11111111-1111-4111-8111-111111111101', 1, 'v1.0 — Initial Architectural Blueprint', 'published', 'admin@medipath.demo', '2026-01-05T08:00:00.000Z', 'Published initial 4-floor architectural spatial graph with accessible elevator links.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.floors (id, building_id, level_number, code, name, name_ta, subtitle, subtitle_ta, elevation_meters, svg_width, svg_height, svg_plan, is_published) VALUES ('44444444-4444-4444-8444-444444444400', '22222222-2222-4222-8222-222222222201', 0, 'L0', 'Ground Atrium & Emergency', 'தரை தளம் — வரவேற்பு மற்றும் அவசர சிகிச்சை', 'Main Entrance, Reception, Emergency Trauma, Billing, Cafeteria & Help Desk', 'பிரதான நுழைவாயில், வரவேற்பு, அவசர சிகிச்சை, கட்டணம், உணவகம் மற்றும் உதவி மையம்', 0, 1000, 640, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 640" role="img" aria-label="L0 architectural floor plan">
INSERT INTO public.floors (id, building_id, level_number, code, name, name_ta, subtitle, subtitle_ta, elevation_meters, svg_width, svg_height, svg_plan, is_published) VALUES ('44444444-4444-4444-8444-444444444401', '22222222-2222-4222-8222-222222222201', 1, 'L1', 'Diagnostics & Pharmacy', 'முதல் தளம் — பரிசோதனைக் கூடம் மற்றும் மருந்தகம்', 'Clinical Laboratory, Radiology Imaging (MRI / CT) & Central Pharmacy', 'மருத்துவ பரிசோதனைக் கூடம், கதிரியக்கவியல் (MRI / CT) மற்றும் மருந்தகம்', 4.2, 1000, 640, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 640" role="img" aria-label="L1 architectural floor plan">
INSERT INTO public.floors (id, building_id, level_number, code, name, name_ta, subtitle, subtitle_ta, elevation_meters, svg_width, svg_height, svg_plan, is_published) VALUES ('44444444-4444-4444-8444-444444444402', '22222222-2222-4222-8222-222222222201', 2, 'L2', 'Specialist Outpatient Wings', 'இரண்டாம் தளம் — சிறப்பு மருத்துவப் பிரிவுகள்', 'Cardiology, Neurology, Orthopaedics & General Medicine Clinics', 'இதயவியல், நரம்பியல், எலும்பியல் மற்றும் பொது மருத்துவம்', 8.4, 1000, 640, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 640" role="img" aria-label="L2 architectural floor plan">
INSERT INTO public.floors (id, building_id, level_number, code, name, name_ta, subtitle, subtitle_ta, elevation_meters, svg_width, svg_height, svg_plan, is_published) VALUES ('44444444-4444-4444-8444-444444444403', '22222222-2222-4222-8222-222222222201', 3, 'L3', 'Critical Care & Inpatient Wards', 'மூன்றாம் தளம் — தீவிர சிகிச்சை மற்றும் உள்நோயாளி வார்டுகள்', 'Intensive Care Unit (ICU) & Private Inpatient Recovery Suites', 'தீவிர சிகிச்சைப் பிரிவு (ICU) மற்றும் உள்நோயாளி அறைகள்', 12.6, 1000, 640, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 640" role="img" aria-label="L3 architectural floor plan">
