INSERT INTO public.departments (id, hospital_id, floor_id, slug, code, name, name_ta, wing, wing_ta, summary, summary_ta, description, description_ta, clinical_lead, open_hours, open_hours_ta, is_emergency, accent_color, amenities) VALUES ('55555555-5555-4555-8555-555555555502', '11111111-1111-4111-8111-111111111101', '44444444-4444-4444-8444-444444444402', 'cardiology', 'CARD-02', 'Cardiology & Vascular Center', 'இதயவியல் மற்றும் இரத்த நாளப் பிரிவு', 'West Pavilion · Level 2', 'மேற்குப் பகுதி · தளம் 2', 'Non-invasive echocardiography, interventional cardiology consultations, and cardiac rehab.', 'இதய ஒலி வரைபடம் (Echo), இதய மருத்துவ ஆலோசனை மற்றும் மறுவாழ்வு சேவைகள்.', 'Located on the calm second-level west wing, the Cardiology Pavilion brings diagnostics, vascular screening, and outpatient consultation suites together with zero-threshold access from the Central Atrium Elevators.', 'இரண்டாம் தள மேற்குப் பகுதியில் அமைந்துள்ள இதயவியல் பிரிவு, மைய மின்தூக்கிகள் வழியாக எளிதில் அணுகக்கூடிய நவீன ஆலோசனை அறைகளைக் கொண்டுள்ளது.', 'Dr. Kavitha Ramanathan, MD, DM', 'Mon–Sat · 08:00 – 19:00', 'திங்கள்–சனி · 08:00 – 19:00', false, '#174C50', '["ECG Bay","Echocardiography","Step-free access","Quiet waiting lounge"]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.departments (id, hospital_id, floor_id, slug, code, name, name_ta, wing, wing_ta, summary, summary_ta, description, description_ta, clinical_lead, open_hours, open_hours_ta, is_emergency, accent_color, amenities) VALUES ('55555555-5555-4555-8555-555555555503', '11111111-1111-4111-8111-111111111101', '44444444-4444-4444-8444-444444444402', 'neurology', 'NEUR-02', 'Neurology & Stroke Unit', 'நரம்பியல் மற்றும் பக்கவாதப் பிரிவு', 'Southwest Pavilion · Level 2', 'தென்மேற்குப் பகுதி · தளம் 2', 'Comprehensive headache, movement disorder, epilepsy, and rapid stroke recovery clinics.', 'நரம்பியல் கோளாறுகள், வலிப்பு மற்றும் பக்கவாத சிகிச்சைக்கான சிறப்பு மருத்துவம்.', 'Equipped with electroencephalography suites and neuro-rehabilitation rooms adjacent to Level 1 MRI imaging for seamless patient transfers.', 'முதல் தள MRI பிரிவுடன் நேரடி மின்தூக்கி இணைப்பு கொண்ட நரம்பியல் மற்றும் பக்கவாத சிகிச்சைப் பிரிவு.', 'Dr. Aravind Subramanian, MD, DM', 'Mon–Sat · 08:30 – 18:30', 'திங்கள்–சனி · 08:30 – 18:30', false, '#102C35', '["EEG Lab","Stroke Clinic","Wheelchair wide doors"]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.departments (id, hospital_id, floor_id, slug, code, name, name_ta, wing, wing_ta, summary, summary_ta, description, description_ta, clinical_lead, open_hours, open_hours_ta, is_emergency, accent_color, amenities) VALUES ('55555555-5555-4555-8555-555555555504', '11111111-1111-4111-8111-111111111101', '44444444-4444-4444-8444-444444444402', 'orthopaedics', 'ORTH-02', 'Orthopaedics & Kinetic Rehab', 'எலும்பியல் மற்றும் மூட்டு மறுவாழ்வு', 'Southeast Pavilion · Level 2', 'தென்கிழக்குப் பகுதி · தளம் 2', 'Joint care, sports medicine, fracture follow-up, and gait physiotherapy studio.', 'மூட்டு மருத்துவம், விளையாட்டு காயங்கள், எலும்பு முறிவு மற்றும் பிசியோதெரபி.', 'Step-free consultation suites linked directly to the East Clinical Elevators for effortless wheelchair and stretcher movement.', 'கிழக்கு மின்தூக்கிகளுக்கு அருகில் அமைந்துள்ள தடையற்ற எலும்பியல் மற்றும் பிசியோதெரபி மையம்.', 'Dr. Vikramaditya Nair, MS (Ortho)', 'Mon–Sat · 08:00 – 20:00', 'திங்கள்–சனி · 08:00 – 20:00', false, '#B7A58A', '["Cast Room","Physiotherapy Studio","East Lift Access"]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.departments (id, hospital_id, floor_id, slug, code, name, name_ta, wing, wing_ta, summary, summary_ta, description, description_ta, clinical_lead, open_hours, open_hours_ta, is_emergency, accent_color, amenities) VALUES ('55555555-5555-4555-8555-555555555505', '11111111-1111-4111-8111-111111111101', '44444444-4444-4444-8444-444444444402', 'general-medicine', 'GMED-02', 'General & Preventive Medicine', 'பொது மற்றும் தடுப்பு மருத்துவம்', 'Northeast Pavilion · Level 2', 'வடகிழக்குப் பகுதி · தளம் 2', 'Primary internal medicine, metabolic care, executive health reviews, and vaccinations.', 'முதன்மை உள்மருத்துவம், நீரிழிவு பராமரிப்பு மற்றும் முழு உடல் பரிசோதனை.', 'Our primary consultation hub offering coordinated care across diagnostic laboratory, imaging, and specialty referrals.', 'பரிசோதனைக் கூடம் மற்றும் சிறப்பு மருத்துவர்களுடன் இணைந்த ஒருங்கிணைந்த பொது மருத்துவ சேவை.', 'Dr. Meenakshi Sundaram, MD', 'Mon–Sun · 07:30 – 21:00', 'திங்கள்–ஞாயிறு · 07:30 – 21:00', false, '#174C50', '["Health Checkups","Vaccination Suite","Rapid Queue"]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.departments (id, hospital_id, floor_id, slug, code, name, name_ta, wing, wing_ta, summary, summary_ta, description, description_ta, clinical_lead, open_hours, open_hours_ta, is_emergency, accent_color, amenities) VALUES ('55555555-5555-4555-8555-555555555501', '11111111-1111-4111-8111-111111111101', '44444444-4444-4444-8444-444444444400', 'emergency', 'EMER-00', 'Emergency & Acute Trauma', 'அவசர மற்றும் அதிர்ச்சி சிகிச்சை', 'West Ground Gate A · Level 0', 'மேற்கு நுழைவு A · தரை தளம்', '24/7 resuscitation bays, rapid triage, ambulance bay, and immediate imaging lift access.', '24/7 அவசர சிகிச்சை, ஆம்புலன்ஸ் நுழைவு மற்றும் உடனடி CT பரிசோதனை இணைப்பு.', 'Direct ground-level ambulance ramp access on the West facade with an unencumbered emergency triage corridor and dedicated elevator priority.', 'மேற்குப் புற ஆம்புலன்ஸ் சாய்வு பாதை வழியாக நேரடி அணுகல் கொண்ட 24 மணி நேர அவசர சிகிச்சைப் பிரிவு.', 'Dr. Arjun Krishnan, MD (EM)', '24 Hours · 7 Days', '24 மணி நேரமும் திறந்திருக்கும்', true, '#B83227', '["24/7 Resuscitation","Ambulance Bay","Zero-step Ramp"]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.departments (id, hospital_id, floor_id, slug, code, name, name_ta, wing, wing_ta, summary, summary_ta, description, description_ta, clinical_lead, open_hours, open_hours_ta, is_emergency, accent_color, amenities) VALUES ('55555555-5555-4555-8555-555555555506', '11111111-1111-4111-8111-111111111101', '44444444-4444-4444-8444-444444444401', 'laboratory', 'LAB-01', 'Clinical Pathology & Laboratory', 'மருத்துவ பரிசோதனைக் கூடம்', 'West Diagnostics · Level 1', 'மேற்குப் பகுதி · தளம் 1', 'Phlebotomy, hematology, biochemistry, and microbiology sample collection bays.', 'இரத்தப் பரிசோதனை, உயிர்வேதியியல் மற்றும் நுண்ணுயிரியல் ஆய்வுக்கூடம்.', 'Quiet private sample-collection cubicles with digital queue synchronization and rapid digital test notification.', 'தனிப்பட்ட மாதிரி சேகரிப்பு அறைகள் மற்றும் டிஜிட்டல் வரிசை கண்காணிப்பு வசதி கொண்ட ஆய்வுக்கூடம்.', 'Dr. Shanthi Rajagopal, MD (Path)', 'Mon–Sun · 06:30 – 20:00', 'திங்கள்–ஞாயிறு · 06:30 – 20:00', false, '#174C50', '["Fasting Lounge","Pediatric Phlebotomy","Digital Queue"]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.departments (id, hospital_id, floor_id, slug, code, name, name_ta, wing, wing_ta, summary, summary_ta, description, description_ta, clinical_lead, open_hours, open_hours_ta, is_emergency, accent_color, amenities) VALUES ('55555555-5555-4555-8555-555555555507', '11111111-1111-4111-8111-111111111101', '44444444-4444-4444-8444-444444444401', 'radiology', 'RAD-01', 'Radiology & Diagnostic Imaging', 'கதிரியக்கவியல் மற்றும் ஸ்கேன் மையம்', 'Southwest Diagnostics · Level 1', 'தென்மேற்குப் பகுதி · தளம் 1', '3T MRI, low-dose CT, digital X-ray, and ultrasound imaging suites.', '3T MRI, CT ஸ்கேன், டிஜிட்டல் எக்ஸ்-ரே மற்றும் அல்ட்ராசவுண்ட் பரிசோதனைகள்.', 'Shielded diagnostic wing featuring wide patient changing suites and calm indirect lighting prior to MRI/CT scans.', 'MRI மற்றும் CT ஸ்கேன் பரிசோதனைகளுக்கான அமைதியான காத்திருப்பு மற்றும் பாதுகாப்பு வசதிகள்.', 'Dr. Deepak Venkatesh, MD (Rad)', 'Mon–Sun · 07:00 – 22:00', 'திங்கள்–ஞாயிறு · 07:00 – 22:00', false, '#102C35', '["3T MRI","128-Slice CT","Ultrasound","Accessible Changing Rooms"]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.departments (id, hospital_id, floor_id, slug, code, name, name_ta, wing, wing_ta, summary, summary_ta, description, description_ta, clinical_lead, open_hours, open_hours_ta, is_emergency, accent_color, amenities) VALUES ('55555555-5555-4555-8555-555555555508', '11111111-1111-4111-8111-111111111101', '44444444-4444-4444-8444-444444444401', 'pharmacy', 'PHM-01', 'Central Pharmacy & Counseling', 'மத்திய மருந்தகம்', 'Southeast Pavilion · Level 1', 'தென்கிழக்குப் பகுதி · தளம் 1', 'Outpatient prescription fulfillment, clinical pharmacist counseling, and cold-chain biologics.', 'மருந்து விநியோகம் மற்றும் மருந்தாளர் ஆலோசனை மையம்.', 'Accessible directly off the East Clinical Elevators so discharged patients and clinic visitors collect medications swiftly.', 'கிழக்கு மின்தூக்கிக்கு அருகில் அமைந்துள்ள மருந்தகம்; விரைவான மருந்து விநியோக வசதி.', 'R. Lakshmi Narayanan, M.Pharm', '24 Hours · 7 Days', '24 மணி நேரமும் திறந்திருக்கும்', false, '#B7A58A', '["24/7 Counter","Private Counseling Desk","East Lift Access"]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.departments (id, hospital_id, floor_id, slug, code, name, name_ta, wing, wing_ta, summary, summary_ta, description, description_ta, clinical_lead, open_hours, open_hours_ta, is_emergency, accent_color, amenities) VALUES ('55555555-5555-4555-8555-555555555509', '11111111-1111-4111-8111-111111111101', '44444444-4444-4444-8444-444444444403', 'icu', 'ICU-03', 'Intensive Care Unit (ICU)', 'தீவிர சிகிச்சைப் பிரிவு (ICU)', 'West Critical Wing · Level 3', 'மேற்குப் பகுதி · தளம் 3', 'Multidisciplinary critical care, neuro-cardiac monitoring, and scheduled family briefing room.', 'பல்துறை தீவிர சிகிச்சை மற்றும் குடும்பத்தினர் சந்திப்பு அறை.', 'Controlled quiet critical care wing. Visitor entry passes through the Level 3 Nurse & Family Lounge with staff check-in.', 'பாதுகாக்கப்பட்ட தீவிர சிகிச்சைப் பிரிவு; பார்வையாளர்கள் செவிலியர் வரவேற்பு வழியாக அனுமதிக்கப்படுவர்.', 'Dr. Sanjay Balakrishnan, MD, FNB', '24/7 Care · Visitor Slots 11:00 & 17:00', '24/7 சிகிச்சை · பார்வையாளர் நேரம் 11:00 & 17:00', false, '#B83227', '["Family Briefing Suite","Controlled Access","Nurse Concierge"]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.departments (id, hospital_id, floor_id, slug, code, name, name_ta, wing, wing_ta, summary, summary_ta, description, description_ta, clinical_lead, open_hours, open_hours_ta, is_emergency, accent_color, amenities) VALUES ('55555555-5555-4555-8555-555555555510', '11111111-1111-4111-8111-111111111101', '44444444-4444-4444-8444-444444444403', 'inpatient-wards', 'WARD-03', 'Inpatient Recovery Suites', 'உள்நோயாளி சிகிச்சை அறைகள்', 'East Terrace Wing · Level 3', 'கிழக்குப் பகுதி · தளம் 3', 'Daylight-filled single recovery rooms, step-down surgical wards, and attendant lounges.', 'தனியார் சிகிச்சை அறைகள் மற்றும் உதவியாளர் ஓய்வறைகள்.', 'Acoustic recovery rooms overlooking the campus garden terrace with direct East Clinical Elevator transport.', 'இயற்கை வெளிச்சமும் அமைதியும் கொண்ட உள்நோயாளி சிகிச்சை அறைகள்.', 'Matron Grace Selvaraj, MSc Nursing', '24/7 Inpatient Care · Visiting 09:00 – 20:00', '24/7 பராமரிப்பு · பார்வையாளர் நேரம் 09:00 – 20:00', false, '#174C50', '["Private Suites","Attendant Lounge","East Lift Core"]'::jsonb) ON CONFLICT (id) DO NOTHING;
