INSERT INTO public.doctors (id, hospital_id, department_id, destination_id, slug, full_name, full_name_ta, title, title_ta, specialty, specialty_ta, qualifications, languages, experience_years, consultation_fee, bio, bio_ta, portrait_initials, is_active) VALUES ('77777777-7777-4777-8777-777777777701', '11111111-1111-4111-8111-111111111101', '55555555-5555-4555-8555-555555555502', '66666666-6666-4666-8666-666666666614', 'dr-kavitha-ramanathan', 'Dr. Kavitha Ramanathan', 'டாக்டர் கவிதா ராமநாதன்', 'Senior Consultant & Lead Cardiologist', 'மூத்த இதயவியல் ஆலோசகர்', 'Interventional Cardiology & Heart Failure', 'இதயவியல் மற்றும் இதய செயலிழப்பு சிகிச்சை', 'MBBS, MD (General Medicine), DM (Cardiology)', ARRAY['English', 'Tamil']::text[], 16, 900, 'Specializes in preventive coronary assessment, structural echocardiography, and patient-centered cardiac recovery planning.', 'இதய ஒலி வரைபடம் மற்றும் இதய நோய் தடுப்பு சிகிச்சையில் 16 ஆண்டுகள் அனுபவம் கொண்டவர்.', 'KR', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.doctors (id, hospital_id, department_id, destination_id, slug, full_name, full_name_ta, title, title_ta, specialty, specialty_ta, qualifications, languages, experience_years, consultation_fee, bio, bio_ta, portrait_initials, is_active) VALUES ('77777777-7777-4777-8777-777777777702', '11111111-1111-4111-8111-111111111101', '55555555-5555-4555-8555-555555555503', '66666666-6666-4666-8666-666666666615', 'dr-aravind-subramanian', 'Dr. Aravind Subramanian', 'டாக்டர் அரவிந்த் சுப்பிரமணியன்', 'Head of Neurosciences & Stroke', 'நரம்பியல் துறைத் தலைவர்', 'Stroke Medicine & Movement Disorders', 'பக்கவாத சிகிச்சை மற்றும் நரம்பியல்', 'MBBS, MD, DM (Neurology)', ARRAY['English', 'Tamil']::text[], 14, 950, 'Directs the acute stroke pathway and outpatient migraine and epilepsy rehabilitation clinics.', 'பக்கவாத அவசர சிகிச்சை மற்றும் நரம்பியல் மறுவாழ்வுப் பிரிவை வழிநடத்துபவர்.', 'AS', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.doctors (id, hospital_id, department_id, destination_id, slug, full_name, full_name_ta, title, title_ta, specialty, specialty_ta, qualifications, languages, experience_years, consultation_fee, bio, bio_ta, portrait_initials, is_active) VALUES ('77777777-7777-4777-8777-777777777703', '11111111-1111-4111-8111-111111111101', '55555555-5555-4555-8555-555555555504', '66666666-6666-4666-8666-666666666616', 'dr-vikramaditya-nair', 'Dr. Vikramaditya Nair', 'டாக்டர் விக்ரமாதித்யா நாயர்', 'Consultant Orthopaedic & Joint Surgeon', 'எலும்பியல் மற்றும் மூட்டு அறுவை சிகிச்சை நிபுணர்', 'Joint Preservation & Sports Orthopaedics', 'மூட்டு பாதுகாப்பு மற்றும் விளையாட்டு மருத்துவம்', 'MBBS, MS (Orthopaedics), Fellowship in Arthroplasty', ARRAY['English', 'Tamil', 'Malayalam']::text[], 12, 850, 'Focuses on minimally invasive ligament reconstruction, gait mechanics, and structured physiotherapy recovery.', 'மூட்டு மற்றும் தசைநார் அறுவை சிகிச்சை மற்றும் பிசியோதெரபி மறுவாழ்வில் நிபுணர்.', 'VN', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.doctors (id, hospital_id, department_id, destination_id, slug, full_name, full_name_ta, title, title_ta, specialty, specialty_ta, qualifications, languages, experience_years, consultation_fee, bio, bio_ta, portrait_initials, is_active) VALUES ('77777777-7777-4777-8777-777777777704', '11111111-1111-4111-8111-111111111101', '55555555-5555-4555-8555-555555555505', '66666666-6666-4666-8666-666666666617', 'dr-meenakshi-sundaram', 'Dr. Meenakshi Sundaram', 'டாக்டர் மீனாட்சி சுந்தரம்', 'Lead Physician — Internal Medicine', 'முதன்மை பொது மருத்துவ ஆலோசகர்', 'Internal & Metabolic Medicine', 'உள்மருத்துவம் மற்றும் நீரிழிவு பராமரிப்பு', 'MBBS, MD (Internal Medicine)', ARRAY['English', 'Tamil']::text[], 19, 650, 'Leads holistic primary care, diabetes and hypertension optimization, and multi-specialty diagnostic coordination.', 'முதன்மை பொது மருத்துவம், நீரிழிவு மற்றும் இரத்த அழுத்தப் பராமரிப்பில் 19 ஆண்டு அனுபவம்.', 'MS', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.doctors (id, hospital_id, department_id, destination_id, slug, full_name, full_name_ta, title, title_ta, specialty, specialty_ta, qualifications, languages, experience_years, consultation_fee, bio, bio_ta, portrait_initials, is_active) VALUES ('77777777-7777-4777-8777-777777777705', '11111111-1111-4111-8111-111111111101', '55555555-5555-4555-8555-555555555501', '66666666-6666-4666-8666-666666666604', 'dr-arjun-krishnan', 'Dr. Arjun Krishnan', 'டாக்டர் அர்ஜுன் கிருஷ்ணன்', 'Director of Emergency Medicine', 'அவசர சிகிச்சைத் துறை இயக்குநர்', 'Acute Trauma & Rapid Triage', 'அவசர அதிர்ச்சி சிகிச்சை', 'MBBS, MD (Emergency Medicine)', ARRAY['English', 'Tamil']::text[], 11, 700, 'Coordinates 24/7 resuscitation protocols and rapid trauma transfer between West Gate A and Level 1 CT imaging.', '24/7 அவசர சிகிச்சை மற்றும் விரைவு CT பரிசோதனை ஒருங்கிணைப்பாளர்.', 'AK', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.doctors (id, hospital_id, department_id, destination_id, slug, full_name, full_name_ta, title, title_ta, specialty, specialty_ta, qualifications, languages, experience_years, consultation_fee, bio, bio_ta, portrait_initials, is_active) VALUES ('77777777-7777-4777-8777-777777777706', '11111111-1111-4111-8111-111111111101', '55555555-5555-4555-8555-555555555509', '66666666-6666-4666-8666-666666666619', 'dr-sanjay-balakrishnan', 'Dr. Sanjay Balakrishnan', 'டாக்டர் சஞ்சய் பாலகிருஷ்ணன்', 'Chief Intensivist', 'தீவிர சிகிச்சைப் பிரிவுத் தலைவர்', 'Critical Care & Respiratory Support', 'தீவிர சிகிச்சை மற்றும் சுவாசப் பராமரிப்பு', 'MBBS, MD, FNB (Critical Care)', ARRAY['English', 'Tamil']::text[], 15, 1000, 'Leads multidisciplinary ICU rounds and structured daily family communication conferences.', 'தீவிர சிகிச்சைப் பிரிவு கண்காணிப்பு மற்றும் குடும்பத்தினர் ஆலோசனைத் தலைவர்.', 'SB', true) ON CONFLICT (id) DO NOTHING;
