INSERT INTO public.hospital_services (id, hospital_id, department_id, destination_id, slug, name, name_ta, category, summary, summary_ta, details, details_ta, preparation_notes, preparation_notes_ta, availability, availability_ta, turnaround_estimate) VALUES ('e0000000-0000-4000-8000-000000000001', '11111111-1111-4111-8111-111111111101', '55555555-5555-4555-8555-555555555506', '66666666-6666-4666-8666-666666666610', 'diagnostic-laboratory-panels', 'Diagnostic Laboratory & Phlebotomy', 'ஆய்வக இரத்தப் பரிசோதனைகள்', 'diagnostic', 'Fasting metabolic panels, hematology, thyroid, and cardiac biomarker testing on Level 1.', 'தளம் 1-இல் விரைவான இரத்தப் பரிசோதனை மற்றும் மாதிரி சேகரிப்பு.', 'Patients with pre-booked orders may check in at QR Checkpoint MP-QR-L1-LAB for priority phlebotomy cubicle assignment.', 'முன்பதிவு செய்த நோயாளர்கள் MP-QR-L1-LAB வழியாக முன்னுரிமை டோக்கன் பெறலாம்.', '8–10 hours fasting required for lipid and fasting glucose panels; plain water permitted.', 'சர்க்கரை மற்றும் கொழுப்பு பரிசோதனைக்கு 8–10 மணி நேர வெறும் வயிறு அவசியம்.', 'Daily · 06:30 – 20:00', 'தினமும் · 06:30 – 20:00', '2–4 hours digital report') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.hospital_services (id, hospital_id, department_id, destination_id, slug, name, name_ta, category, summary, summary_ta, details, details_ta, preparation_notes, preparation_notes_ta, availability, availability_ta, turnaround_estimate) VALUES ('e0000000-0000-4000-8000-000000000002', '11111111-1111-4111-8111-111111111101', '55555555-5555-4555-8555-555555555507', '66666666-6666-4666-8666-666666666611', 'mri-ct-imaging-suite', '3T MRI & Low-Dose CT Imaging', '3T MRI மற்றும் CT ஸ்கேன் சேவை', 'diagnostic', 'High-resolution neuro, cardiac, and orthopaedic imaging with step-free stretcher access.', 'மூளை, இதயம் மற்றும் எலும்பு மூட்டுகளுக்கான துல்லியமான ஸ்கேன் பரிசோதனை.', 'Includes quiet preparation bays and dedicated accessible changing suites adjacent to West Imaging Corridor.', 'சக்கர நாற்காலி வசதியுடன் கூடிய தனி உடை மாற்றும் அறைகள் மற்றும் அமைதியான காத்திருப்பு இடம்.', 'Remove metallic jewelry; inform staff of implants or contrast allergies prior to scan.', 'உலோக ஆபரணங்களை அகற்றவும்; ஒவ்வாமை அல்லது உள்வைப்புகள் இருந்தால் முன்பே தெரிவிக்கவும்.', 'Daily · 07:00 – 22:00 (24/7 Emergency CT)', 'தினமும் · 07:00 – 22:00', 'Same-day radiologist review') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.hospital_services (id, hospital_id, department_id, destination_id, slug, name, name_ta, category, summary, summary_ta, details, details_ta, preparation_notes, preparation_notes_ta, availability, availability_ta, turnaround_estimate) VALUES ('e0000000-0000-4000-8000-000000000003', '11111111-1111-4111-8111-111111111101', '55555555-5555-4555-8555-555555555508', '66666666-6666-4666-8666-666666666612', '24-hour-pharmacy-dispensary', '24/7 Clinical Pharmacy Dispensary', '24 மணி நேர மருந்தகம்', 'pharmacy', 'Outpatient prescriptions, dosage counseling in English & Tamil, and discharge medicine packs.', 'மருந்து விநியோகம் மற்றும் தமிழ்/ஆங்கிலத்தில் மருந்து பயன்பாட்டு வழிகாட்டல்.', 'Located directly off the East Clinical Elevators on Level 1 to minimize walking after clinic visits.', 'கிழக்கு மின்தூக்கிகளுக்கு அருகில் தளம் 1-இல் அமைந்துள்ளது.', 'Bring your consultation summary or digital prescription reference.', 'மருத்துவர் பரிந்துரைச் சீட்டு அல்லது டிஜிட்டல் குறிப்பை எடுத்து வரவும்.', 'Open 24 Hours', '24 மணி நேரமும் திறந்திருக்கும்', '10–15 min counter fulfillment') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.hospital_services (id, hospital_id, department_id, destination_id, slug, name, name_ta, category, summary, summary_ta, details, details_ta, preparation_notes, preparation_notes_ta, availability, availability_ta, turnaround_estimate) VALUES ('e0000000-0000-4000-8000-000000000004', '11111111-1111-4111-8111-111111111101', NULL, '66666666-6666-4666-8666-666666666603', 'wheelchair-escort-assistance', 'Wheelchair & Patient Escort Service', 'சக்கர நாற்காலி & வழிகாட்டி உதவி', 'support', 'Complimentary porter escort and wheelchair assistance from Main Entrance or Emergency Gate.', 'பிரதான நுழைவாயிலிலிருந்து இலவச சக்கர நாற்காலி மற்றும் பணியாளர் உதவி.', 'Request assistance online before arrival or at the Ground Atrium Help Desk for seamless clinic transfers across floors.', 'மருத்துவமனைக்கு வரும் முன்போ அல்லது உதவி மையத்திலோ உடனடியாக முன்பதிவு செய்யலாம்.', 'Specify your arrival entrance and target department when submitting a request.', 'நீங்கள் வரும் நுழைவாயில் மற்றும் செல்ல வேண்டிய துறையைக் குறிப்பிடவும்.', '24 Hours · Ground Atrium Dispatch', '24 மணி நேரமும்', 'Within 5 minutes at Ground Atrium') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.hospital_services (id, hospital_id, department_id, destination_id, slug, name, name_ta, category, summary, summary_ta, details, details_ta, preparation_notes, preparation_notes_ta, availability, availability_ta, turnaround_estimate) VALUES ('e0000000-0000-4000-8000-000000000005', '11111111-1111-4111-8111-111111111101', NULL, '66666666-6666-4666-8666-666666666605', 'billing-insurance-concierge', 'Billing & Cashless Insurance Desk', 'கட்டணம் & காப்பீட்டு உதவி மையம்', 'billing', 'Transparent itemized billing, insurance pre-authorization, and rapid discharge settlement.', 'மருத்துவக் கட்டண விவரங்கள் மற்றும் காப்பீட்டு ஒப்புதல் சேவை.', 'Located on the Ground Concourse East Wing with private consultation counters.', 'தரை தளம் கிழக்குப் பகுதியில் தனிப்பட்ட ஆலோசனை மையங்கள் உள்ளன.', 'Carry valid photo ID and insurer policy card for pre-authorization.', 'அடையாள அட்டை மற்றும் காப்பீட்டு அட்டையை எடுத்து வரவும்.', 'Mon–Sat · 07:30 – 20:30', 'திங்கள்–சனி · 07:30 – 20:30', '15 min outpatient clearance') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.hospital_services (id, hospital_id, department_id, destination_id, slug, name, name_ta, category, summary, summary_ta, details, details_ta, preparation_notes, preparation_notes_ta, availability, availability_ta, turnaround_estimate) VALUES ('e0000000-0000-4000-8000-000000000006', '11111111-1111-4111-8111-111111111101', NULL, '66666666-6666-4666-8666-666666666606', 'garden-terrace-cafeteria', 'Garden Terrace Dining & Nutrition', 'தோட்ட உணவகம் & ஊட்டச்சத்து மையம்', 'amenity', 'Fresh balanced meals, diabetic-friendly options, and calm courtyard seating.', 'சத்தான உணவு வகைகள் மற்றும் அமைதியான தோட்ட இருக்கைகள்.', 'Accessible along the Level 0 Northeast Garden Gallery.', 'தரை தளம் வடகிழக்கு தோட்டப் பகுதியில் அமைந்துள்ளது.', 'No appointment required; attendant seating open daily.', 'பார்வையாளர்கள் மற்றும் குடும்பத்தினருக்குத் தினமும் திறந்திருக்கும்.', 'Daily · 06:30 – 21:30', 'தினமும் · 06:30 – 21:30', 'Immediate service') ON CONFLICT (id) DO NOTHING;
