INSERT INTO public.qr_checkpoints (id, hospital_id, floor_id, node_id, code, label, label_ta, location_hint, location_hint_ta, is_active) VALUES ('c0000000-0000-4000-8000-000000000004', '11111111-1111-4111-8111-111111111101', '44444444-4444-4444-8444-444444444401', 'a0000000-0000-4000-8000-000000000207', 'MP-QR-L1-LAB', 'Level 1 Diagnostics Junction', 'முதல் தளம் பரிசோதனைக்கூட QR முனையம்', 'Outside Clinical Laboratory Entrance', 'ஆய்வுக்கூட நுழைவாயில் அருகில்', true) ON CONFLICT (id) DO NOTHING;
