INSERT INTO public.announcements (id, hospital_id, title, title_ta, body, body_ta, severity, is_active) VALUES ('f3000000-0000-4000-8000-000000000001', '11111111-1111-4111-8111-111111111101', 'Sample Campus Notice — Architectural Map v1.0 Active', 'மாதிரி வளாக அறிவிப்பு — 3D வரைபடம் v1.0 செயல்பாட்டில் உள்ளது', 'All four levels of Aurelia Pavilion (Sample Campus) are open with Central & East accessible elevators active. Use QR checkpoints at lobby desks to launch turn-by-turn 3D navigation.', 'ஆரேலியா பெவிலியன் (மாதிரி வளாகம்) நான்கு தளங்களும் மைய மற்றும் கிழக்கு மின்தூக்கிகளுடன் செயல்பாட்டில் உள்ளன.', 'info', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.announcements (id, hospital_id, title, title_ta, body, body_ta, severity, is_active) VALUES ('f3000000-0000-4000-8000-000000000002', '11111111-1111-4111-8111-111111111101', 'Level 3 ICU Sterile Bypass Restricted to Authorized Staff', 'தளம் 3 ICU உள்வழி பாதை மருத்துவப் பணியாளர்களுக்கு மட்டுமே', 'Visitors heading to the ICU should take Central Atrium Elevators to Level 3 and check in via the North Gallery Nurse Concierge.', 'ICU பார்வையாளர்கள் மைய மின்தூக்கி வழியாக தளம் 3 வடக்கு நடைபாதையில் செவிலியர் வரவேற்பை அணுகவும்.', 'advisory', true) ON CONFLICT (id) DO NOTHING;
